(()=>{const c=[...document.querySelectorAll('.article-sidebar nav a[href^="#"]')];if(c.length&&"IntersectionObserver"in window){const t=new IntersectionObserver(e=>{for(const r of e)r.isIntersecting&&c.forEach(n=>n.classList.toggle("active",n.hash==="#"+r.target.id))},{rootMargin:"-110px 0px -65% 0px"});c.forEach(e=>{const r=document.getElementById(e.hash.slice(1));r&&t.observe(r)})}const o=document.querySelector("#service-calculator");if(o){const t=()=>{const e=Object.fromEntries(new FormData(o)),r=Number(e.hours)||0,n=Number(e.hourly)||0,s=Number(e.materials)||0,a=Math.min(95,Math.max(0,Number(e.margin)||0)),i=(r*n+s)/(1-a/100);document.querySelector("#price-result").value=new Intl.NumberFormat("en-US",{style:"currency",currency:e.currency||"USD"}).format(i)};o.addEventListener("input",t),t()}})();
